export interface WindowState {
  totalItems: number;
  pageSize: number;
  page: number;
}

export type WindowCommand =
  | { type: "page"; page: number }
  | { type: "pageSize"; pageSize: number };

export interface WindowResult {
  state: WindowState;
  warning: string | null;
  rangeStart: number;
  rangeEnd: number;
}

const SIZES: ReadonlySet<number> = new Set([10, 25, 50, 100]);

export function updateWindow(state: WindowState, command: WindowCommand): WindowResult {
  validateState(state);
  let next: WindowState = { ...state };
  let warning: string | null = null;

  if (command.type === "page") {
    if (!Number.isSafeInteger(command.page) || command.page <= 0) {
      throw new TypeError("page must be a positive safe integer");
    }
    const pageCount = Math.max(1, Math.ceil(state.totalItems / state.pageSize));
    if (command.page < pageCount) {
      next.page = command.page;
    } else {
      warning = "Page is out of range";
    }
  } else if (command.type === "pageSize") {
    if (!Number.isSafeInteger(command.pageSize) || command.pageSize <= 0) {
      throw new TypeError("pageSize must be a positive safe integer");
    }
    if (SIZES.has(command.pageSize)) {
      next = { ...state, pageSize: command.pageSize, page: 1 };
    } else {
      warning = "Unsupported page size";
    }
  } else {
    throw new TypeError("unknown command");
  }

  const rangeStart = next.totalItems === 0
    ? 0
    : (next.page - 1) * next.pageSize + 1;
  const rangeEnd = next.totalItems === 0
    ? 0
    : Math.min(next.page * next.pageSize, next.totalItems);

  return { state: next, warning, rangeStart, rangeEnd };
}

function validateState(state: WindowState): void {
  if (!Number.isSafeInteger(state.totalItems) || state.totalItems < 0) {
    throw new TypeError("totalItems must be a nonnegative safe integer");
  }
  if (!Number.isSafeInteger(state.pageSize) || state.pageSize <= 0) {
    throw new TypeError("pageSize must be a positive safe integer");
  }
  const pageCount = Math.max(1, Math.ceil(state.totalItems / state.pageSize));
  if (!Number.isSafeInteger(state.page) || state.page <= 0 || state.page > pageCount) {
    throw new TypeError("state page is out of range");
  }
}

