import { updateWindow, type WindowCommand, type WindowResult, type WindowState } from "./solution";

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    throw new Error(`${message}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }
}
function throwsType(fn: () => unknown, message: string): void {
  try { fn(); } catch (error) {
    if (error instanceof TypeError) return;
    throw new Error(`${message}: wrong error type`);
  }
  throw new Error(`${message}: did not throw`);
}

const state: WindowState = { totalItems: 101, pageSize: 10, page: 1 };
const command: WindowCommand = { type: "page", page: 11 };
const pageResult: WindowResult = updateWindow(state, command);
equal(pageResult, { state: { totalItems: 101, pageSize: 10, page: 11 }, warning: null, rangeStart: 101, rangeEnd: 101 }, "last partial page");
equal(state, { totalItems: 101, pageSize: 10, page: 1 }, "state is not mutated");
assert(pageResult.state !== state, "successful command returns a new state object");

const outOfRange = updateWindow(state, { type: "page", page: 12 });
equal(outOfRange, { state: { totalItems: 101, pageSize: 10, page: 1 }, warning: "Page is out of range", rangeStart: 1, rangeEnd: 10 }, "out-of-range page");
assert(outOfRange.state !== state, "rejected command still returns a new state object");

const resized = updateWindow({ totalItems: 60, pageSize: 10, page: 4 }, { type: "pageSize", pageSize: 25 });
equal(resized, { state: { totalItems: 60, pageSize: 25, page: 1 }, warning: null, rangeStart: 1, rangeEnd: 25 }, "supported page size resets page");
const unsupported = updateWindow({ totalItems: 60, pageSize: 10, page: 4 }, { type: "pageSize", pageSize: 20 });
equal(unsupported, { state: { totalItems: 60, pageSize: 10, page: 4 }, warning: "Unsupported page size", rangeStart: 31, rangeEnd: 40 }, "unsupported page size");

for (const size of [10, 25, 50, 100]) {
  assert(updateWindow({ totalItems: 1, pageSize: 10, page: 1 }, { type: "pageSize", pageSize: size }).warning === null, `supported size ${size}`);
}
equal(updateWindow({ totalItems: 0, pageSize: 10, page: 1 }, { type: "page", page: 1 }), { state: { totalItems: 0, pageSize: 10, page: 1 }, warning: null, rangeStart: 0, rangeEnd: 0 }, "empty window");
equal(updateWindow({ totalItems: 0, pageSize: 10, page: 1 }, { type: "page", page: 2 }).warning, "Page is out of range", "empty window has one navigable page");

throwsType(() => updateWindow({ totalItems: -1, pageSize: 10, page: 1 }, { type: "page", page: 1 }), "negative total");
throwsType(() => updateWindow({ totalItems: 1.5, pageSize: 10, page: 1 }, { type: "page", page: 1 }), "fractional total");
throwsType(() => updateWindow({ totalItems: 1, pageSize: 0, page: 1 }, { type: "page", page: 1 }), "zero state page size");
throwsType(() => updateWindow({ totalItems: 1, pageSize: 10, page: 0 }, { type: "page", page: 1 }), "zero state page");
throwsType(() => updateWindow(state, { type: "page", page: 0 }), "zero requested page");
throwsType(() => updateWindow(state, { type: "page", page: 1.2 }), "fractional requested page");
throwsType(() => updateWindow(state, { type: "pageSize", pageSize: Number.MAX_SAFE_INTEGER + 1 }), "unsafe requested size");
throwsType(() => updateWindow(state, { type: "other" } as unknown as WindowCommand), "unknown command");

